/* Reports use the completed calculation snapshot, never the current editable form. */
(()=>{'use strict';
const style=`@page{size:A4 portrait;margin:14mm 12mm}*{box-sizing:border-box}body{margin:0;background:#eaf0f5;color:#21364c;font:13px/1.6 Tahoma,Arial,sans-serif}.paper{max-width:950px;margin:25px auto;padding:36px;background:white;box-shadow:0 5px 30px #1232}header{border-bottom:3px solid #009cc9;padding-bottom:16px;display:flex;justify-content:space-between;gap:25px}h1{font-size:21px;margin:5px 0}h2{font-size:17px;border-bottom:1px solid #c8d9e7;margin-top:25px;padding-bottom:6px}h3{font-size:14px;break-after:avoid}.brand{color:#0085a7;font-size:10px;letter-spacing:2px}.stamp{text-align:right;min-width:160px;font-size:11px}.badge{border:1px solid #a3d8eb;border-radius:20px;padding:6px 15px;background:#f3fbff;color:#008bb6;font-size:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:18px 0}.metric{border:1px solid #bacfdf;border-radius:8px;padding:10px 8px;font-size:10px}.metric b{display:block;color:#0089b2;font-size:18px}.metric small{font-size:10px}figure{margin:16px 0;border:1px solid #bfd2df;border-radius:8px;padding:10px}svg{width:100%;height:auto;display:block}figcaption,.note{font-size:11px;color:#587084}table{width:100%;border-collapse:collapse;font-size:11px;margin:12px 0 20px;table-layout:fixed}th,td{border:1px solid #d1dfe8;padding:7px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#edf4f9;color:#39546b}tr:nth-child(even){background:#f8fbfd}.performance table{font-size:10px}.performance th,.performance td{padding:5px}.summary{border-left:4px solid #00a1b7;background:#f0fafb;padding:12px 18px}.warning{background:#fff6e5;border-left:3px solid #d59d3d;padding:10px}.controls{position:sticky;top:0;background:#123246;color:white;text-align:center;padding:12px}.controls button{border:0;background:#55d9c7;color:#123;border-radius:7px;padding:10px 18px;font:inherit;cursor:pointer}.controls span{margin-left:12px;font-size:12px}footer{border-top:1px solid #c4d4df;padding-top:12px;font-size:10px;color:#5e7486}a{color:#0081a5}@media(max-width:600px){.paper{padding:16px;margin:0}.metrics{grid-template-columns:repeat(2,1fr)}header{display:block}.stamp{text-align:left}.performance{overflow:auto}.performance table{min-width:700px}.controls span{display:block}}@media print{body{background:white;font-size:10px}.paper{padding:0;margin:0;box-shadow:none;max-width:none}.controls{display:none}h1{font-size:17px}h2{font-size:14px;break-after:avoid}table{font-size:9px}th,td{padding:5px}thead{display:table-header-group}tr{break-inside:avoid}.metrics{grid-template-columns:repeat(5,1fr)}.metric b{font-size:15px}.performance{overflow:visible}.performance table{font-size:8px;min-width:0}figure,.metrics{break-inside:avoid}.page-start{break-before:page}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}a{color:inherit;text-decoration:none}}`;
function build(c,r){
 const av=MWAvailability.evaluate(c,r,c.availability||{}),range=(lo,hi,d=6)=>Math.abs(hi-lo)<1e-12?fmt(lo,d):fmt(lo,d)+' – '+fmt(hi,d),modes=c.amRows.length?c.amRows:[{name:c.modulation,capacity:c.capacity,powerA:c.a.power,powerB:c.b.power,thresholdA:c.a.threshold,thresholdB:c.b.threshold}];
 let html=`<header><div><div class="brand">RADIO COVERAGE LAB · ENGINEERING REPORT</div><h1>รายงานการวิเคราะห์ลิงก์ไมโครเวฟ</h1><div>Microwave Link Budget Report</div><p>เส้นทาง: ${esc(c.a.name)} → ${esc(c.b.name)}<br>${esc(c.linkName)}</p></div><div class="stamp"><span class="badge">${fmt(c.freq,3)} GHz</span><p>ผลคำนวณ: ${esc(new Date(c.calculatedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}))}<br>เวลาประเทศไทย (UTC+7)</p></div></header>`;
 html+='<div class="metrics">'+[['ระยะทาง',fmt(r.distance/1000,3),'km'],['ความถี่',fmt(c.freq,3),'GHz'],['Free-space loss',fmt(r.fspl),'dB'],['RSL design A → B',fmt(r.ab.planned),'dBm'],['Thermal margin A → B',fmt(r.ab.thermal),'dB']].map(([label,value,unit])=>`<div class="metric">${label}<b>${value} <small>${unit}</small></b></div>`).join('')+'</div>';
 html+=`<p class="note">ค่าสรุปด้านบนเป็นโหมดหลัก ${esc(c.modulation)} · RSL design หัก field margin ${fmt(c.margin)} dB แล้ว · งบประมาณต่อ carrier/polarization</p><h2>Path Profile & Fresnel Zone</h2><figure>${profileSVG(c,r)}<figcaption>F1 สูงสุด ${fmt(r.fmax)} m · K=${fmt(c.k,3)} · เกณฑ์ ${fmt(c.clearance)} F1 · ระยะเคลียร์เกณฑ์ต่ำสุด ${fmt(r.minClear)} m${r.worst?' ณ กม. '+fmt(r.worst.x/1000,3)+' / ขวางทาง '+fmt(r.worst.offset)+' m':''} · ภาพขยายแกนตั้ง</figcaption></figure>`;
 html+=reportHTML(c,r);
 html+='<section class="page-start"><h2>3. ภูมิอากาศและ Availability</h2>'+table(['พารามิเตอร์','ค่า / แหล่งที่มา'],[['LogK / dN75',fmt(c.availability?.logK,6)+' / '+fmt(c.availability?.dN75,3)],['R0.01',fmt(c.rainRate)+' mm/h'],['แหล่งข้อมูล',c.availability?.source||'ไม่ระบุ'],['พิกัด lookup',c.availability?.climate?.mode==='auto'?fmt(c.availability.climate.lat,6)+', '+fmt(c.availability.climate.lon,6)+' · กึ่งกลางลิงก์':'กรอกเอง'],['Multipath p0 / ΔG',fmt(av.mp.p0,6)+' % / '+fmt(av.mp.delta,3)+' dB'],['DEM เฉลี่ย ht / mean clearance hc',fmt(av.mp.ht)+' / '+fmt(av.mp.hc)+' m'],...Object.entries(av.rain).map(([pol,v])=>['Rain '+pol+' · γR / A0.01',v.error||fmt(v.gamma,4)+' dB/km / '+fmt(v.a001,3)+' dB'])]);
 if(av.mp.note)html+='<p class="warning">'+esc(av.mp.note)+'</p>';
 html+='<h2>4. สมรรถนะแยกตาม Modulation</h2><p class="note">Throughput เป็นค่าที่กำหนด/เลือกจากคู่มือ ไม่ใช่เวลาที่ AM เลือกใช้โหมดนั้น และไม่รวมความจุ 2+0 โดยอัตโนมัติ</p>';
 html+='<p class="note">สมมติฐานรายงาน: คุณภาพลิงก์ A → B และ B → A เท่ากันสำหรับแต่ละ polarization จึงแสดง H: A ↔ B และ V: A ↔ B โดยใช้ผล A → B เป็นตัวแทนร่วม ไม่ใช่การเฉลี่ยสองทิศทาง หากตั้ง TX/RX ต่างกันต้องตรวจผลแยกทิศทางในหน้าเว็บ</p>';
 for(const dir of ['ab'])for(const pol of [...new Set(av.rows.map(x=>x.pol))]){html+='<h3>'+(dir==='ab'?'A → B':'B → A')+' · '+esc(pol)+' polarization</h3><div class="performance">'+table(['Modulation','Mbps','TX dBm','EIRP dBm','RSL design dBm','RX threshold dBm','Thermal margin dB','Annual availability %','Outage นาที/ปี'],modes.map(m=>{const tx=dir==='ab'?m.powerA:m.powerB,side=dir==='ab'?c.a:c.b,rx=r[dir].planned+tx-side.power,threshold=dir==='ab'?m.thresholdB:m.thresholdA,x=av.rows.find(x=>x.mode===m.name&&x.direction===dir&&x.pol===pol);return [m.name,fmt(m.capacity,1),fmt(tx),fmt(r[dir].eirp+tx-side.power),fmt(rx),fmt(threshold),fmt(rx-threshold),x?.total?range(100-x.total.hi,100-x.total.lo):'ข้อมูลไม่ครบ / นอกขอบเขต',x?.total?range(x.total.lo*5256,x.total.hi*5256,2):'—']}))+'</div>'}
 html+='<h3>Degradation ต่อโหมด</h3>'+table(['Modulation','XPD multipath dB','XPD rain dB'],modes.map(m=>{const ds=c.availability?.modeDegradation?.[m.name]||(c.amRows.length?[null,null]:[c.availability?.mpDeg,c.availability?.rainDeg]);return [m.name,fmt(ds[0]),fmt(ds[1])]}));
 const issues=[...new Set(av.rows.flatMap(x=>x.errors))];if(issues.length)html+='<div class="warning"><b>รายการที่ยังสรุป Availability ไม่ได้</b><ul>'+issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>';
 html+='<p class="note">ช่วงตัวเลขเป็นขอบเขตประมาณการเมื่อ outage จากฝนอยู่นอกช่วงสมการ 0.001–1% ไม่ใช่ค่าจุด · ปีละ 365 วัน · ไม่บวก outage สองทิศทาง เพราะเหตุอาจเกิดพร้อมกัน · ค่าว่างไม่ใช่ 100% availability</p></section>';
 html+=`<h2>5. สรุปผลการประเมิน</h2><div class="summary"><p>เส้นทาง ${esc(c.a.name)} → ${esc(c.b.name)} ระยะ ${fmt(r.distance/1000,3)} km ที่ความถี่ ${fmt(c.freq,3)} GHz ติดตั้งจานสูง ${fmt(c.a.antAGL)} / ${fmt(c.b.antAGL)} m AGL</p><p>${r.clear?'ไม่พบ':'พบ'}การรุกล้ำเกณฑ์ Fresnel ที่เลือกในจุดตัวอย่าง · ระยะเคลียร์ต่ำสุด ${fmt(r.minClear)} m ที่ ${fmt(c.clearance)} F1 / K=${fmt(c.k,3)} · LOS กึ่งกลางต่ำสุด ${fmt(r.minLOS)} m</p><p>โหมดหลัก ${esc(c.modulation)}: RX design A→B / B→A = ${fmt(r.ab.planned)} / ${fmt(r.ba.planned)} dBm และ Thermal margin = ${fmt(r.ab.thermal)} / ${fmt(r.ba.thermal)} dB</p><p>ประเมิน Availability ได้ ${av.rows.filter(x=>x.total).length} จาก ${av.rows.length} รายการทิศทาง/โพลาไรซ์ ดูค่ารายโหมดในตาราง ผลการเลือกขนาดจานตาม Target แสดงแยกในส่วนประเมินขนาดจานด้านล่าง ไม่ใช่ SLA รวมของระบบ</p></div>`;
 html+='<section class="page-start"><h2>6. ประเมินและแนะนำขนาดจานตาม Target Availability</h2>'+MWDish.html(c.dishSizing).replaceAll('<details>','<details open>')+'</section>';
 html+='<h2>7. Equivalent XPD margin · Mₓₚᴅ</h2>'+MWXPD.html(c.mxpd);
 html+='<h2>8. แหล่งข้อมูลและข้อจำกัด</h2>'+table(['รายการ','รายละเอียด'],[['DEM',c.terrain.source],['DEM pixel / sample / corridor',fmt(c.terrain.pixelM)+' m / '+fmt(c.terrain.step)+' m / ±'+fmt(c.terrain.width)+' m'],['ประวัติ preset อุปกรณ์',c.equipmentReference||'กรอกเอง / ไม่ได้เลือก preset']]);
 html+='<p>ข้อมูล preset เป็นประวัติอ้างอิง ค่าจริงที่ใช้คำนวณอาจถูกแก้ไขแล้ว · DEM ไม่ยืนยันต้นไม้/อาคารทั้งหมด และ sample spacing ไม่ใช่ความละเอียด DEM · ไม่ได้ทดสอบ K อื่นหรือกำลังส่ง High Power เพิ่มเติมในรายงานนี้</p><p>Availability เป็นประมาณการด้านการแพร่คลื่นตาม ITU-R P.530-18 / P.838-3 ไม่ใช่ SLA และยังไม่รวม frequency-selective fading, diversity, หิมะเปียก, ไฟฟ้าดับ และอุปกรณ์เสีย · XPD, XPIF และ C/I ไม่ได้ถูกแปลงเป็น degradation อัตโนมัติ</p><p>อ้างอิง: <a href="https://www.itu.int/rec/R-REC-P.530-18-202109-S/en">ITU-R P.530-18</a> · <a href="https://www.itu.int/rec/R-REC-P.838-3-200503-I/en">P.838-3</a> · <a href="https://drive.google.com/drive/folders/1oZImCnSQWQWPqlAmETgxQ1Er7iQHE8IR">คู่มืออุปกรณ์</a></p><footer>Radio Coverage Lab · สร้างจากผลคำนวณที่เสร็จสมบูรณ์ ณ เวลาที่ระบุ · ตรวจทานข้อมูลหน้างานก่อนใช้ออกแบบ</footer>';
 return '<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc('รายงาน Microwave Link · '+c.a.name+' → '+c.b.name)+'</title><style>'+style+'</style></head><body><div class="controls"><button onclick="window.print()">พิมพ์ / บันทึก PDF</button><span>เลือก Save as PDF · A4 · ปิด Headers and footers ของเบราว์เซอร์</span></div><main class="paper">'+html+'</main></body></html>';
}
globalThis.MWReport={build};
for(const id of ['print','download'])$(id).hidden=false;$('print').textContent='รายงาน / Export PDF';$('download').textContent='Export รายงาน HTML';
function current(){if(!result||!lastConfig||$('print').disabled)throw Error('กรุณาคำนวณลิงก์ใหม่ก่อน Export รายงาน');return build(lastConfig,result)}
$('print').onclick=()=>{try{const text=current(),w=window.open('','_blank');if(!w){$('status').textContent='เบราว์เซอร์บล็อกหน้ารายงาน กรุณาอนุญาต pop-up หรือใช้ Export รายงาน HTML';return}w.opener=null;w.document.open();w.document.write(text);w.document.close()}catch(e){$('status').textContent=e.message}};
$('download').onclick=()=>{try{const text=current(),name=(lastConfig.linkName||'microwave').replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,70);download(new Blob([text],{type:'text/html;charset=utf-8'}),name+'-report.html')}catch(e){$('status').textContent=e.message}};
})();
